import styles from './DetailPanel.module.css';
import { useApp } from '../../context/AppContext';

// helper to get the category name, icon, color for an event
function getCategoryInfo(event, categories) {
  const cat = categories.find(c => c.id === event.category);
  return {
    name: cat?.name || 'Uncategorized',
    icon: cat?.icon || '❓',
    color: cat?.color || '#888',
  };
}


// main panel

export default function DetailPanel() {
    const { state, dispatch, openEditEvent } = useApp();
    // find the selected event
    const selectedEvent = state.events.find(e => e.id === state.selectedEventId);
    const { categories } = state;

  return (
    <aside className={styles.detail}>
      <div style={{ padding: 20, color: 'var(--text-muted)', fontSize: 13 }}>
        {selectedEvent ? (
          <div>
            <h3>{getCategoryInfo(selectedEvent, categories).name}</h3>
            <p>{selectedEvent.details}</p>
            <button
              onClick={() => {
                openEditEvent(selectedEvent);
                dispatch({ type: 'SELECT_EVENT', payload: selectedEvent.id });
                }}
                >
                Edit Event
              </button>
          </div>
        ) : (
          "Select an event to view details."
        )}
      </div>
    </aside>
  );
}
